var debug = require('debug')('mendel:tree-hash-walker');
var util = require('util');
var xtend = require('xtend');

var deserialize = require('./tree-deserialiser');
var MendelWalker = require('./tree-walker');

util.inherits(MendelHashWalker, MendelWalker);
module.exports = MendelHashWalker;

function MendelHashWalker(inputHash) {
    debug('init MendelHashWalker');
    if (!(this instanceof MendelHashWalker)) {
        return new MendelHashWalker(inputHash);
    }
    MendelWalker.call(this);

    var result = deserialize(inputHash);
    this.error = result.error;
    this.decoded = result.decoded;

    this.inputHash = inputHash;
    this.pathCount = 0;
}

MendelHashWalker.prototype._resolveBranch = function (module) {
    if (this.error) return {};

    var nextPath;
    var resolved;
    if (this.pathCount >= this.decoded.branches.length) {
        this._error('Tree has more paths than hash');
    } else {
        nextPath = this.decoded.branches[this.pathCount];
        resolved = module.data[nextPath];
        if (!resolved) {
            this._error('Hash branch not found in tree');
        }
    }
    this.pathCount++;
    return {
        index: nextPath,
        resolved: resolved || {},
    };
};

MendelHashWalker.prototype._error = function (msg) {
    this.error = this.error || new Error(msg);
    this.error.code = 'TRVRSL';
    debug(this.error);
};

MendelHashWalker.prototype.found = function () {
    this._result = MendelWalker.prototype.found.call(this);

    if (!this.error && this._result.hash !== this.inputHash) {
        var error = new Error('Tree Hash Mismatch');
        error.code = 'HASHMISS';
        this.error = error;
    }

    return xtend(this._result, {
        error: this.error,
    });
};

/* Copyright 2015, Yahoo Inc.
   Designed by Irae Carvalho
   Copyrights licensed under the MIT License.
   See the accompanying LICENSE file for terms. */

var debug = require('debug')('mendel:tree-variation-walker');
var util = require('util');
var xtend = require('xtend');

var MendelWalker = require('./tree-walker');

util.inherits(MendelVariationWalker, MendelWalker);
module.exports = MendelVariationWalker;

function MendelVariationWalker(_lookupChains, _base, _hash) {
    debug('init MendelVariationWalker');
    if (!(this instanceof MendelVariationWalker)) {
        return new MendelVariationWalker(_lookupChains, _base, _hash);
    }
    MendelWalker.call(this);

    this._lookupChains = _lookupChains;
    this._base = _base;
    this.conflicts = 0;
    this.conflictList = {};
}

MendelVariationWalker.prototype._resolveBranch = function (module) {
    var fileId = module.id;
    var resolved;
    var foundIn = 0;
    var pathIndex = 0;
    for (var i = 0; i < this._lookupChains.length; i++) {
        for (var j = 0; j < this._lookupChains[i].length; j++) {
            var index = module.variations.indexOf(this._lookupChains[i][j]);
            if (-1 !== index) {
                if (!foundIn) {
                    // keep first match, priority by .mendelrc entry order
                    resolved = module.data[index];
                    pathIndex = index;
                }
                if (!foundIn || this._lookupChains[i][j] !== this._base) {
                    // config.base don't cont as conflict
                    foundIn++;
                }
                break;
            }
        }
    }
    if (foundIn > 1) {
        this.conflicts++;
        this.conflictList[fileId] = true;
    }
    return {
        index: pathIndex,
        resolved: resolved,
    };
};

MendelVariationWalker.prototype.found = function () {
    return xtend(MendelWalker.prototype.found.call(this), {
        conflicts: this.conflicts,
        conflictList: this.conflictList,
    });
};

var path = require('path');
var yaml = require('js-yaml');
var fs = require('fs');
var xtend = require('xtend');

function findConfig(where) {
    var parts = where.split(path.sep);

    do {
        var loc = parts.join(path.sep);
        if (!loc) break;

        var config;
        var mendelrc = process.env.MENDELRC || '.mendelrc';
        var rc = path.join(loc, mendelrc);
        if (fs.existsSync(rc)) {
            config = loadFromYaml(rc);
            config.projectRoot = path.dirname(rc);
            return config;
        }

        var packagejson = path.join(loc, 'package.json');
        if (fs.existsSync(packagejson)) {
            var pkg = require(path.resolve(packagejson));
            if (pkg.mendel) {
                config = pkg.mendel;
                config.projectRoot = path.dirname(packagejson);
                return config;
            }
        }

        parts.pop();
    } while (parts.length);

    return {};
}

function loadFromYaml(path) {
    return yaml.load(fs.readFileSync(path, 'utf8'));
}

function load(config, resolvePlugins) {
    if (typeof config === 'string') config = { projectRoot: config };
    if (typeof config !== 'object') config = {};

    var projectRoot = config.projectRoot || config.basedir || process.cwd();

    // support --no-config or {config: false} to skip looking for file configs
    if (config.config !== false) {
        var fileConfig = findConfig(projectRoot);
        // in case we found a file config, assign by priority
        if (fileConfig.projectRoot) {
            config = xtend(fileConfig, config);
            // but force projectRoot to always be consistent
            config.projectRoot = fileConfig.projectRoot;
            // In case this config is passed to mendel-config again
            config.config = false;
        }
    }

    // require only inside conditional
    if (config['base-config'] || JSON.stringify(config) === '{}') {
        // This requires node 6 - can use ES6 features
        return require('./src')(config, resolvePlugins);
    } else {
        config.basedir = config.projectRoot;
        // This requires node 0.10 - must be written in ES5
        return require('./legacy')(config);
    }
}

function parseConfig(config) {
    return load(config, false);
}

function devConfig(config) {
    return load(config, true);
}

module.exports = parseConfig;
module.exports.devConfig = devConfig;

/* Copyright 2015, Yahoo Inc.
   Inspired by https://github.com/babel/babel/blob/d06cfe63c272d516dc4d6f1f200b01b8dfdb43b1/packages/babel-cli/src/babel-doctor/rules/has-config.js
   Copyrights licensed under the MIT License.
   See the accompanying LICENSE file for terms. */

var path = require('path');
var xtend = require('xtend');
var defaultConfig = require('./defaults');

module.exports = function (config) {
    var defaults = defaultConfig();

    // merge by priority
    config = xtend(defaults, config);
    config.basedir = config.basedir || defaults.basedir;

    // merge environment based config
    var environment = process.env.MENDEL_ENV || process.env.NODE_ENV;
    if (environment) {
        config.environment = environment;
    }
    var envConfig = config.env[config.environment];
    if (envConfig) {
        config = mergeRecursive(config, envConfig);
    }
    delete config.env;

    // Final parsing
    if (!path.isAbsolute(config.basedir)) {
        config.basedir = path.resolve(config.basedir);
    }
    if (!path.isAbsolute(config.outdir)) {
        config.outdir = path.join(config.basedir, config.outdir);
    }
    if (!path.isAbsolute(config.bundlesoutdir)) {
        config.bundlesoutdir = path.join(config.outdir, config.bundlesoutdir);
    }
    if (!path.isAbsolute(config.serveroutdir)) {
        config.serveroutdir = path.join(config.outdir, config.serveroutdir);
    }
    config.bundles = parseBundles(config.bundles);

    return config;
};

function parseBundles(bundles) {
    // istanbul ignore if
    if (!bundles) return bundles;
    var bundlesArray = Object.keys(bundles).filter(Boolean);
    if (!bundlesArray.length) return bundlesArray;

    return bundlesArray
        .map(function (bundleName) {
            var bundle = bundles[bundleName];

            bundle.id = bundleName;
            bundle.bundleName = bundleName;
            bundle.manifest = bundleName + '.manifest.json';
            flattenFilenameArrays(bundle);

            return bundle;
        })
        .filter(Boolean);
}

function mergeRecursive(dest, src) {
    for (var key in src) {
        // istanbul ignore else
        if (Object.hasOwn(src, key)) {
            if (isObject(dest[key]) && isObject(src[key])) {
                dest[key] = mergeRecursive(dest[key], src[key]);
            } else {
                dest[key] = src[key];
            }
        }
    }
    return dest;
}

function flattenFilenameArrays(bundle) {
    ['entries', 'require', 'external', 'exclude', 'ignore'].forEach(
        function (param) {
            var inputArray = bundle[param];
            if (!Array.isArray(inputArray)) return;

            var i = 0;
            while (i <= inputArray.length) {
                var item = inputArray[i];
                if (Array.isArray(item)) {
                    Array.prototype.splice.apply(
                        inputArray,
                        [i, 1].concat(item)
                    );
                }
                i++;
            }
        }
    );
}

function isObject(obj) {
    return {}.toString.call(obj).slice(8, -1).toLowerCase() === 'object';
}

